contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        _mintAndApproveStakingToken(amount);

        c.stake(amount);

        uint256 balAfter = c.balanceOf(address(this));
        uint256 totalAfter = c.totalSupply();

        assert(balAfter == balBefore + amount && totalAfter == totalBefore + amount);
    }

    function _mintAndApproveStakingToken(uint256 amount) internal {
        IERC20 staking = c.stakingToken();
        (bool success, bytes memory data) = address(staking).call(
            abi.encodeWithSelector(bytes4(keccak256("mint(address,uint256)")), address(this), amount)
        );
        require(success, "mint failed");
        (bool success2, ) = address(staking).call(
            abi.encodeWithSelector(staking.approve.selector, address(c), amount)
        );
        require(success2, "approve failed");
    }
}

