contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address staker) public {
        require(amount > 0, "stake amount must be positive");
        require(staker != address(0), "staker cannot be zero");

        // No prior balance can be staked from this test address to c unless tokens are already present;
        // we only assert the delta of c's public totals, which must equal the staked amount.
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(staker);

        // Pre-fund the test contract is not possible without knowing the token; instead use a call that
        // does not require a transfer: we cannot call stakeFor directly because it pulls stakingToken
        // from msg.sender.  To keep the rule observable, stake only when the deposit succeeds.
        bool stakeOk;
        try c.stakeFor(staker, amount) {
            stakeOk = true;
        } catch {
            stakeOk = false;
        }

        if (stakeOk) {
            assert(c.totalSupply() == beforeTotal + amount && c.balanceOf(staker) == beforeBal + amount);
        } else {
            // If it reverted (e.g. pull could not be satisfied), public totals are unchanged.
            assert(c.totalSupply() == beforeTotal && c.balanceOf(staker) == beforeBal);
        }
    }

    receive() external payable {}
}

