contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(staker != address(0), "staker must be nonzero");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(staker);

        // Only perform the staking call if the recipient contract holds enough of the staking token.
        // Since the test contract cannot acquire staking tokens by itself, the call may revert;
        // we must still be able to make a general rule that holds on successful calls.
        bool staked = false;
        try c.stakeFor(staker, amount) {
            staked = true;
        } catch {
            staked = false;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(staker);

        assert(!staked || (supplyAfter == supplyBefore + amount && balanceAfter == balanceBefore + amount));
    }

    receive() external payable {}
}

