        uint256 afterTotal = c.totalSupply();
        uint256 afterUserPaid = c.userRewardPerTokenPaid(staker, rewardToken);
        uint256 afterRewardStored = c.rewardData(rewardToken);

        assert(
            afterClaimable == 0 &&
            afterBalance == beforeBalance &&
            afterTotal == beforeTotal &&
            afterUserPaid >= beforeUserPaid &&
            afterUserPaid >= beforeUserPaid + (beforeClaimable * 1e18) / (beforeBalance == 0 ? 1 : beforeBalance) &&
            afterRewardStored >= beforeRewardStored
        );
