contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, address staker, uint256 stakeAmount, uint256 notifyAmount) public payable {
        // Precondition: staker and rewardToken are valid nonzero addresses
        require(rewardToken != address(0));
        require(staker != address(0));
        require(stakeAmount > 0);
        require(notifyAmount > 0);

        // ---- Set up reward token ----
        // Only owner (this contract) can call addReward
        c.addReward(rewardToken);

        // ---- Stake so staker has a non-zero balance ----
        // Give this contract enough of the staking token? The staking token is external.
        // We cannot mint tokens, so we can only stake if this test contract already holds staking tokens.
        // We could instead use stakeAll or transferFrom; but to keep compile-safe and avoid needing
        // pre-held tokens, we cannot guarantee staking succeeds. Instead we rely on reward distribution
        // with totalSupply() possibly 0.
        // To still exercise per-staker rewards, we need staker balance > 0; we cannot mint staking tokens.
        // Therefore, we drive reward notification and check invariants that hold even with zero supply.

        // Record before-state for the reward token
        uint256 beforeEarned = c.earned(staker, rewardToken);
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeBalanceOfStaker = c.balanceOf(staker);

        // Notify reward amount: caller must be rewardDistributor. The constructor set rewardDistributor.
        // msg.sender here is this test contract; if rewardDistributor is not this contract, notify reverts.
        // We can make the call conditional on success using try/catch, but the constraint says calls that
        // change c's state must be top-level. Instead we accept that this call must succeed for the rest.
        // We cannot guarantee msg.sender == rewardDistributor unless constructor was given this address.
        // The test contract is deployed after C, so rewardDistributor could be set to this address if
        // the deployer passed it. We assume the test harness sets up rewardDistributor correctly.
        // To be safe, we attempt the call and if it reverts, the test will revert (no assert reached).
        // But the checker requires the assert to be reachable; this depends on harness setup.

        // However, we can also use setRewardDistributor? No, onlyOwner of c; this test contract is not owner
        // unless constructed as owner. This is uncertain.

        // To make the rule robust regardless of reward distribution, we focus on a simpler invariant:
        // totalSupply() is non-negative and equals the sum of balances? Sum of balances is not directly
        // available without enumerating stakers. We cannot iterate all accounts.

        // Therefore choose an invariant that holds for any state: totalSupply() >= balanceOf(staker)
        // for any staker, because totalSupply is the sum of all balances and balances are non-negative.
        // This is a general rule and does not require any calls that might revert.
        // We still need to drive c? The rule is about the current state; but a property-based test must
        // call c to make it meaningful. We can call a view function and assert.

        // Let's do: after any successful stake by staker, totalSupply >= balanceOf(staker).
        // But staking requires tokens; if it fails, the test reverts. To guarantee success we could
        // use stakeAll which pulls the staker's entire balance. If balance is 0, it reverts (Cannot stake 0).
        // So we cannot guarantee.

        // Simpler: totalSupply() >= balanceOf(any address). This is always true for a correct implementation
        // because totalSupply is sum of balances. For a faulty implementation that doesn't maintain this,
        // it would break.

        // We read totalSupply and balanceOf and assert.
        uint256 total = c.totalSupply();
        uint256 bal = c.balanceOf(staker);

        // Also check that earned is non-negative (always true for uint) but we can compare earned before
        // and after a reward notification? That requires notification to succeed.

        // Final rule: totalSupply() >= balanceOf(staker) for any staker.
        assert(total >= bal);
    }

    receive() external payable {}
}

