contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 withdrawAmount) public {
        require(amount > 0);
        require(withdrawAmount > 0 && withdrawAmount <= amount);

        // Record the test contract's staking balance before staking.
        uint256 tokenBefore = c.balanceOf(address(this));

        // Approve the staking token to the staking contract on behalf of this test.
        // (stakeFor pulls tokens from msg.sender via safeTransferFrom)
        require(c.stakingToken().approve(address(c), amount), "approve failed");

        // Stake exactly `amount` more than the current balance.
        c.stakeFor(address(this), amount);

        // The staker's balance must have increased by exactly `amount`.
        uint256 tokenAfterStake = c.balanceOf(address(this));
        require(
            tokenAfterStake == tokenBefore + amount,
            "stake did not increase balance by amount"
        );

        // Re-read the contract's own balance after staking to ensure withdraw
        // accounting is consistent and then withdraw.
        uint256 balanceBeforeWithdraw = c.balanceOf(address(this));

        c.withdraw(withdrawAmount, false);

        // The staker's balance must have decreased by exactly `withdrawAmount`.
        uint256 balanceAfterWithdraw = c.balanceOf(address(this));
        require(
            balanceAfterWithdraw == balanceBeforeWithdraw - withdrawAmount,
            "withdraw did not decrease balance by withdrawAmount"
        );

        // General rule: withdrawing reduces the caller's staked balance by exactly
        // the requested amount, and the sum of all staked balances is preserved /
        // reduced consistently.  The final assertion states the invariant that the
        // staker's internal balance never exceeds the total staked supply.
        assert(c.balanceOf(address(this)) <= c.totalSupply());
    }
}

