contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _for, uint256 _amount) public {
        require(_amount > 0, "amount must be positive");
        require(_for != address(0), "recipient must be nonzero");

        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(_for);

        // ensure the test contract has enough staking tokens and has approved c
        // stakingToken() is a public getter returning IERC20
        address staking = address(c.stakingToken());
        // attempt to move tokens from the test contract into c; if the test contract
        // lacks balance this call will revert and the property is vacuously fine only
        // if we avoid requiring success. Instead, we just call stakeFor and observe.
        (bool ok, ) = address(staking).call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), type(uint256).max)
        );

        bool reverted;
        try c.stakeFor(_for, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 supplyAfter = c.totalSupply();
            uint256 balAfter = c.balanceOf(_for);
            assert(supplyAfter == supplyBefore + _amount);
            assert(balAfter == balBefore + _amount);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

