contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 migrateAmount) public {
        // Fresh c: totalSupply is initially 0 and contract holds 0 staking tokens.
        // Only staking (via transferFrom) can increase both balance and totalSupply,
        // withdrawing decreases both.

        // Reject amounts that would make staking transferFrom fail due to balance/allowance.
        require(stakeAmount == 0 || c.stakingToken().balanceOf(address(this)) >= stakeAmount);

        c.stake(stakeAmount);

        uint256 supplyAfterStake = c.totalSupply();
        uint256 selfBalAfterStake = c.stakingToken().balanceOf(address(this));

        // Equal only if the full amount moved and no pre-existing balance.
        assert(supplyAfterStake == selfBalAfterStake);

        // The migrator path can also increase totalSupply without moving tokens from this
        // test contract, so only attempt it when the test contract is the migrator.
        bool migratorIsSelf = (c.migrator() == address(this));
        if (migratorIsSelf && migrateAmount > 0) {
            require(c.stakingToken().balanceOf(address(this)) >= migrateAmount);
            c.stake(migrateAmount);
            uint256 supplyAfterMigrate = c.totalSupply();
            uint256 selfBalAfterMigrate = c.stakingToken().balanceOf(address(this));
            assert(supplyAfterMigrate == selfBalAfterMigrate);
        } else {
            assert(c.totalSupply() == c.stakingToken().balanceOf(address(this)));
        }

        // Withdraw half of the staked balance and check the sum-of-balances invariant again.
        uint256 bal = c.balanceOf(address(this));
        uint256 withdrawAmount = bal / 2;
        if (withdrawAmount > 0) {
            c.withdraw(withdrawAmount, false);
            uint256 supplyAfterWithdraw = c.totalSupply();
            uint256 selfBalAfterWithdraw = c.stakingToken().balanceOf(address(this));
            assert(supplyAfterWithdraw == selfBalAfterWithdraw);
        }

        // The general rule: total staked (sum of balances) never exceeds the staking
        // tokens actually held by the contract.
        assert(c.totalSupply() <= c.stakingToken().balanceOf(address(c)));
    }

    receive() external payable {}
}

