contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 spendAmount) public payable {
        require(depositAmount > 0 && spendAmount > 0);

        // Read-Only Pre-Setup (using existing getters)
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 claimBefore = c.claimableRewards(address(this), address(0));

        uint256 supplyAfter;
        uint256 balAfter;
        bool reverted;

        // Perform a state-changing action on c that is NOT stake/withdraw.
        // We need a function that changes state without modifying _balances/_totalSupply.
        // setRewardDistributor requires onlyOwner; we are NOT owner, so it will revert.
        // That still lets us check that no state changes.
        try c.setRewardDistributor(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        supplyAfter = c.totalSupply();
        balAfter = c.balanceOf(address(this));

        // If the call did not revert (would only happen if we are owner, which we shouldn't be),
        // then the distributor changed but staking accounting must stay unchanged.
        // In all cases, non-stake functions must not alter totalSupply or balances.
        assert(supplyAfter == supplyBefore && balAfter == balBefore);
    }

    receive() external payable {}
}

